<?php
declare(strict_types=1);
require_once __DIR__.'/banking_connection_provider.php';require_once __DIR__.'/estate_bank.php';
const GSZ_BANK_SLOTS=['sparkasse'=>'Sparkasse · Geschäftskonto','volksbank1'=>'Volksbank · Immobilienkonto 1','volksbank2'=>'Volksbank · Immobilienkonto 2'];
function bankingSlot(string $slot):string {if(!isset(GSZ_BANK_SLOTS[$slot]))throw new InvalidArgumentException('Unbekannter Kontobereich.');return $slot;}
function bankingReady(PDO $pdo):bool {return (bool)$pdo->query("SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='bank_connections'")->fetchColumn();}
function bankingGet(PDO $pdo,string $slot,int $admin,bool $lock=false):?array {$q=$pdo->prepare('SELECT * FROM bank_connections WHERE slot=? AND admin_id=?'.($lock?' FOR UPDATE':''));$q->execute([bankingSlot($slot),$admin]);return $q->fetch()?:null;}
function bankingKey(?string $testPath=null,bool $create=false):string {
 $path=$testPath??__DIR__.'/secrets/bank-connections.key';$dir=dirname($path);if(is_link($dir)||is_link($path))throw new RuntimeException('GSZ_BANK_KEY_PATH');if(!is_dir($dir)&&!$create)throw new RuntimeException('GSZ_BANK_KEY_MISSING');if(!is_dir($dir)&&!mkdir($dir,0700,true)&&!is_dir($dir))throw new RuntimeException('GSZ_BANK_KEY_STORAGE');$real=realpath($dir);$public=realpath(dirname(__DIR__).'/public');$webroot=empty($_SERVER['DOCUMENT_ROOT'])?false:realpath((string)$_SERVER['DOCUMENT_ROOT']);if(!$real||($public&&($real===$public||str_starts_with($real,$public.'/')))||($webroot&&($real===$webroot||str_starts_with($real,$webroot.'/'))))throw new RuntimeException('GSZ_BANK_KEY_PUBLIC');
