}
function bankingSeal(array $data,string $key):string {if(strlen($key)!==32)throw new RuntimeException('GSZ_BANK_KEY_LENGTH');$nonce=random_bytes(12);$cipher=openssl_encrypt(json_encode($data,JSON_THROW_ON_ERROR),'aes-256-gcm',$key,OPENSSL_RAW_DATA,$nonce,$tag,'GSZ-bank-v1',16);if($cipher===false)throw new RuntimeException('GSZ_BANK_ENCRYPTION');return json_encode(['v'=>1,'n'=>base64_encode($nonce),'c'=>base64_encode($cipher),'t'=>base64_encode($tag)],JSON_THROW_ON_ERROR);}
function bankingOpen(string $raw,string $key):array {if(strlen($raw)>200000||strlen($key)!==32)throw new RuntimeException('GSZ_BANK_CIPHER_LIMIT');$r=json_decode($raw,true,8,JSON_THROW_ON_ERROR);if(!is_array($r)||($r['v']??null)!==1)throw new RuntimeException('GSZ_BANK_CIPHER_FORMAT');$nonce=base64_decode($r['n']??'',true);$tag=base64_decode($r['t']??'',true);$cipher=base64_decode($r['c']??'',true);if($nonce===false||strlen($nonce)!==12||$tag===false||strlen($tag)!==16||$cipher===false)throw new RuntimeException('GSZ_BANK_CIPHER_FORMAT');$plain=openssl_decrypt($cipher,'aes-256-gcm',$key,OPENSSL_RAW_DATA,$nonce,$tag,'GSZ-bank-v1');if($plain===false)throw new RuntimeException('GSZ_BANK_CIPHER_AUTH');$data=json_decode($plain,true,32,JSON_THROW_ON_ERROR);if(!is_array($data))throw new RuntimeException('GSZ_BANK_CIPHER_FORMAT');return $data;}
function bankingTx(PDO $pdo,callable $fn):mixed {$pdo->beginTransaction();try{$out=$fn();$pdo->commit();return $out;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
function bankingWithLock(PDO $pdo,string $slot,callable $work):mixed {$name='gsz_bank_'.substr(hash('sha256',(string)$pdo->query('SELECT DATABASE()')->fetchColumn()),0,24).'_'.bankingSlot($slot);$q=$pdo->prepare('SELECT GET_LOCK(?,0)');$q->execute([$name]);if(!(int)$q->fetchColumn())throw new RuntimeException('Bankverbindung wird bereits bearbeitet. Bitte kurz warten.');try{return $work();}finally{$q=$pdo->prepare('SELECT RELEASE_LOCK(?)');$q->execute([$name]);}}
function bankingStart(PDO $pdo,int $admin,string $slot,string $institution,string $type,GszEnableBankingClient $client,string $key):string {return bankingWithLock($pdo,$slot,fn()=>bankingStartWork($pdo,$admin,$slot,$institution,$type,$client,$key));}
function bankingStartWork(PDO $pdo,int $admin,string $slot,string $institution,string $type,GszEnableBankingClient $client,string $key):string {
 bankingSlot($slot);if($admin<1)throw new RuntimeException('Inhaberanmeldung erforderlich.');$owner=$pdo->prepare('SELECT admin_id FROM bank_connections WHERE slot=?');$owner->execute([$slot]);$ownerId=$owner->fetchColumn();if($ownerId!==false&&(int)$ownerId!==$admin)throw new RuntimeException('Bankverbindung gehört zum anderen Inhaberzugang.');$old=bankingGet($pdo,$slot,$admin);if($old&&$old['status']==='connected'&&strtotime($old['consent_until'].' UTC')>time())throw new RuntimeException('Bestehende aktive Verbindung zuerst bewusst lokal trennen.');$state=bin2hex(random_bytes(32));$url=$client->authorize($institution,$state,$type);bankingTx($pdo,function()use($pdo,$admin,$slot,$institution,$state,$key,$type){$check=$pdo->prepare('SELECT admin_id FROM bank_connections WHERE slot=? FOR UPDATE');$check->execute([$slot]);$owner=$check->fetchColumn();if($owner!==false&&(int)$owner!==$admin)throw new RuntimeException('Bankverbindung gehört zum anderen Inhaberzugang.');$current=bankingGet($pdo,$slot,$admin,true);if($current&&$current['status']==='connected'&&strtotime($current['consent_until'].' UTC')>time())throw new RuntimeException('Verbindung inzwischen erneuert.');$pdo->prepare("INSERT INTO bank_connections(slot,admin_id,institution,status,state_hash,pending_until,payload) VALUES(?,?,?,'pending',?,UTC_TIMESTAMP()+INTERVAL 10 MINUTE,?) ON DUPLICATE KEY UPDATE institution=VALUES(institution),status='pending',state_hash=VALUES(state_hash),pending_until=VALUES(pending_until),payload=VALUES(payload),last_error_code=''")->execute([$slot,$admin,$institution,hash('sha256',$state),bankingSeal(['psu_type'=>$type],$key)]);gszAudit($pdo,$admin,'bank_authorization_started',['slot'=>$slot,'read_only'=>true]);});return $url;
}
/** Protocol-only callback: no session cookie required and no account binding or provider API call. */
function bankingReceiveCallback(PDO $pdo,string $state,string $code,string $key):void {
 if(!preg_match('/^[a-f0-9]{64}$/D',$state)||$code===''||strlen($code)>2048||preg_match('/[\x00-\x20\x7f]/',$code))throw new RuntimeException('Bankrückmeldung ungültig/abgelaufen.');bankingTx($pdo,function()use($pdo,$state,$code,$key){$q=$pdo->prepare("SELECT * FROM bank_connections WHERE state_hash=? AND status='pending' AND pending_until>UTC_TIMESTAMP() FOR UPDATE");$q->execute([hash('sha256',$state)]);$c=$q->fetch();if(!$c)throw new RuntimeException('Bankrückmeldung ungültig/abgelaufen.');$payload=bankingOpen($c['payload'],$key);$payload['code']=$code;$pdo->prepare("UPDATE bank_connections SET payload=?,status='awaiting_owner',state_hash=NULL,pending_until=UTC_TIMESTAMP()+INTERVAL 5 MINUTE WHERE slot=?")->execute([bankingSeal($payload,$key),$c['slot']]);});
}
function bankingExchange(PDO $pdo,int $admin,string $slot,GszEnableBankingClient $client,string $key):void {bankingWithLock($pdo,$slot,fn()=>bankingExchangeWork($pdo,$admin,$slot,$client,$key));}
function bankingExchangeWork(PDO $pdo,int $admin,string $slot,GszEnableBankingClient $client,string $key):void {
 $c=bankingGet($pdo,$slot,$admin);if(!$c||$c['status']!=='awaiting_owner'||strtotime($c['pending_until'].' UTC')<time())throw new RuntimeException('Bankfreigabe fehlt/abgelaufen.');$payload=bankingOpen($c['payload'],$key);$result=$client->exchange((string)($payload['code']??''));if(($result['aspsp']['country']??'')!=='DE'||($result['aspsp']['name']??'')!==$c['institution']||($result['psu_type']??'')!==$payload['psu_type'])throw new RuntimeException('GSZ_BANK_SESSION_INSTITUTION');$accounts=[];foreach($result['accounts'] as $a){if(!is_string($a['uid']??null)||!preg_match('/^[a-zA-Z0-9-]{1,100}$/D',$a['uid'])||($a['currency']??'')!=='EUR')continue;$iban=bankIban((string)($a['account_id']['iban']??''));$accounts[]=['uid'=>$a['uid'],'iban'=>$iban,'name'=>mb_substr((string)($a['name']??''),0,190)];}if(!$accounts)throw new RuntimeException('Keine eindeutig freigegebenen EUR-Konten mit IBAN vorhanden.');$new=['session_id'=>$result['session_id'],'accounts'=>$accounts];bankingTx($pdo,function()use($pdo,$admin,$slot,$c,$new,$result,$key){$old=bankingGet($pdo,$slot,$admin,true);if(!$old||$old['payload']!==$c['payload']||$old['status']!=='awaiting_owner')throw new RuntimeException('Bankfreigabe inzwischen geändert.');$pdo->prepare("UPDATE bank_connections SET payload=?,status='choose_account',consent_until=?,pending_until=NULL WHERE slot=?")->execute([bankingSeal($new,$key),gmdate('Y-m-d H:i:s',strtotime($result['access']['valid_until'])),$slot]);gszAudit($pdo,$admin,'bank_authorization_received',['slot'=>$slot,'read_only'=>true]);});
}
function bankingBind(PDO $pdo,int $admin,string $slot,string $uid,int $businessAccount,string $key):void {bankingWithLock($pdo,$slot,fn()=>bankingBindWork($pdo,$admin,$slot,$uid,$businessAccount,$key));}
function bankingBindWork(PDO $pdo,int $admin,string $slot,string $uid,int $businessAccount,string $key):void {
 bankingSlot($slot);bankingTx($pdo,function()use($pdo,$admin,$slot,$uid,$businessAccount,$key){$c=bankingGet($pdo,$slot,$admin,true);if(!$c||$c['status']!=='choose_account'||strtotime($c['consent_until'].' UTC')<=time())throw new RuntimeException('Aktuelle Bankfreigabe erforderlich.');$payload=bankingOpen($c['payload'],$key);$chosen=null;foreach($payload['accounts'] as $a)if(hash_equals($a['uid'],$uid))$chosen=$a;if(!$chosen)throw new RuntimeException('Konto war nicht freigegeben.');$iban=bankIban($chosen['iban']);$hash=hash('sha256',$iban);$business=$slot==='sparkasse';$target=$business?'bank_accounts':'estate_bank_accounts';$targetId=$business?$businessAccount:($slot==='volksbank1'?1:2);if($targetId<1)throw new RuntimeException('Internes Zielkonto auswählen.');bankAssertIbanBinding($pdo,$target,$targetId,$hash,true);$q=$pdo->prepare('SELECT id,import_iban_hash FROM '.$target.' WHERE id=? FOR UPDATE');$q->execute([$targetId]);$account=$q->fetch();if(!$account||($account['import_iban_hash']&&!hash_equals($account['import_iban_hash'],$hash)))throw new RuntimeException('Interne Kontoidentität abweichend; keine Vermischung.');$pdo->prepare('UPDATE '.$target.' SET import_iban_hash=? WHERE id=?')->execute([$hash,$targetId]);$payload['account']=$chosen;unset($payload['accounts']);$pdo->prepare("UPDATE bank_connections SET status='connected',business_account_id=?,estate_account_id=?,iban_hash=?,payload=?,last_error_code='' WHERE slot=?")->execute([$business?$targetId:null,$business?null:$targetId,$hash,bankingSeal($payload,$key),$slot]);gszAudit($pdo,$admin,'bank_account_bound',['slot'=>$slot,'target_id'=>$targetId,'read_only'=>true]);});
}
function bankingCsv(array $rows):string {$f=fopen('php://temp','w+');fputcsv($f,['id','booked_on','value_on','amount','currency','purpose','counterparty'],';','"','');foreach($rows as $r)fputcsv($f,[$r['id'],$r['booked_on'],$r['value_on'],$r['amount'],$r['currency'],$r['purpose'],$r['counterparty']],';','"','');rewind($f);return stream_get_contents($f);}
function bankingRefresh(PDO $pdo,int $admin,string $slot,string $from,string $to,GszEnableBankingClient $client,string $key):array {return bankingWithLock($pdo,$slot,fn()=>bankingRefreshWork($pdo,$admin,$slot,$from,$to,$client,$key));}
function bankingRefreshWork(PDO $pdo,int $admin,string $slot,string $from,string $to,GszEnableBankingClient $client,string $key):array {
 $c=bankingGet($pdo,$slot,$admin);if(!$c||$c['status']!=='connected'||strtotime($c['consent_until'].' UTC')<=time())throw new RuntimeException('Bankverbindung fehlt/abgelaufen. Neu autorisieren.');if($c['last_attempt_at']&&strtotime($c['last_attempt_at'].' UTC')>time()-60)throw new RuntimeException('Bankabfrage frühestens nach60Sekunden erneut möglich.');$pdo->prepare('UPDATE bank_connections SET last_attempt_at=UTC_TIMESTAMP() WHERE slot=?')->execute([$slot]);try{$payload=bankingOpen($c['payload'],$key);$uid=$payload['account']['uid'];$adapter=new GszEnableBankingAccount($client,$uid);$rows=$adapter->transactions($from,$to);$balance=$adapter->balance();$csv=bankingCsv($rows);$map=['id'=>'id','booked_on'=>'booked_on','value_on'=>'value_on','amount'=>'amount','currency'=>'currency','purpose'=>'purpose','counterparty'=>'counterparty'];$values=[];foreach($balance['balances']??[] as $b)if(($b['balance_amount']['currency']??'')==='EUR'&&in_array($b['balance_type']??'',['CLBD','ITBD','PRCD'],true))$values[]=$b;$value=count($values)===1?financeCents((string)$values[0]['balance_amount']['amount']):null;$type=count($values)===1?$values[0]['balance_type']:null;$token=null;$conflicts=[];$possible=[];if($rows){if($slot==='sparkasse'){$token=bankPreview($pdo,$admin,(int)$c['business_account_id'],$csv,$map,'iso',';',1000);$q=$pdo->prepare('SELECT payload FROM bank_imports WHERE token=? AND admin_id=?');}else{$token=estateBankPreview($pdo,$admin,(int)$c['estate_account_id'],$csv,$map,'iso',';');$q=$pdo->prepare('SELECT payload FROM estate_proposals WHERE token=? AND admin_id=?');}$q->execute([$token,$admin]);$preview=json_decode($q->fetchColumn(),true,64,JSON_THROW_ON_ERROR);$conflicts=$preview['conflicts'];$possible=$preview['possible_duplicates']??[];if(!$conflicts&&!$possible){if($slot==='sparkasse')bankApply($pdo,$admin,$token);else estateBankApply($pdo,$admin,$token);}}
  if($conflicts||$possible)$payload['review_token']=$token;else unset($payload['review_token']);$pdo->prepare("UPDATE bank_connections SET last_success_at=UTC_TIMESTAMP(),last_error_code='',payload=?,balance_cents=?,balance_type=?,balance_at=IF(? IS NULL,NULL,UTC_TIMESTAMP()) WHERE slot=?")->execute([bankingSeal($payload,$key),$value,$type,$value,$slot]);gszAudit($pdo,$admin,'bank_refreshed',['slot'=>$slot,'rows'=>count($rows),'review_required'=>(bool)($conflicts||$possible),'automatic_booking'=>false]);return ['status'=>$conflicts||$possible?'REVIEW':'PASS','rows'=>count($rows),'token'=>$token,'review_required'=>(bool)($conflicts||$possible)];
 }catch(Throwable $e){$pdo->prepare("UPDATE bank_connections SET last_error_code='GSZ_BANK_REFRESH_FAILED' WHERE slot=?")->execute([$slot]);throw new RuntimeException('Bankabruf fehlgeschlagen. Freigabe, Providerstatus und Abrufzeitraum prüfen. Bereits importierte Daten bleiben erhalten.');}
}
function bankingDisconnect(PDO $pdo,int $admin,string $slot):void {bankingWithLock($pdo,$slot,fn()=>bankingDisconnectWork($pdo,$admin,$slot));}
function bankingDisconnectWork(PDO $pdo,int $admin,string $slot):void {bankingTx($pdo,function()use($pdo,$admin,$slot){$old=bankingGet($pdo,$slot,$admin,true);if(!$old)return;$pdo->prepare("UPDATE bank_connections SET status='not_connected',payload='{}',state_hash=NULL,pending_until=NULL,consent_until=NULL,last_error_code='' WHERE slot=?")->execute([$slot]);gszAudit($pdo,$admin,'bank_locally_disconnected',['slot'=>$slot,'transactions_preserved'=>true,'provider_revocation_not_confirmed'=>true]);});}
